import{_ as o,c as t,o as e,a4 as n}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q2：浏览器渲染原理（关键渲染路径）详解","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q2.md","filePath":"frontend/q2.md","lastUpdated":null}'),r={name:"frontend/q2.md"},s=n('<h1 id="q2-浏览器渲染原理-关键渲染路径-详解" tabindex="-1">Q2：浏览器渲染原理（关键渲染路径）详解 <a class="header-anchor" href="#q2-浏览器渲染原理-关键渲染路径-详解" aria-label="Permalink to &quot;Q2：浏览器渲染原理（关键渲染路径）详解&quot;">​</a></h1><p>回答时需讲透 DOM 树、CSSOM 树、渲染树、布局、绘制、合成，以及相关的重排、重绘、合成概念。</p><ul><li><p><strong>DOM 树</strong><br> HTML 解析器通过词法分析和语法分析，将字节 → 字符 → Token → 节点 → DOM 树。解析过程是渐进的，遇到 CSS 和 JS 会阻塞。</p></li><li><p><strong>CSSOM 树</strong><br> CSS 是<strong>阻塞渲染的资源</strong>。浏览器必须下载并解析完所有 CSS，才能构建 CSSOM。CSS 解析可以和 DOM 构建并行，但不能立即显示。CSSOM 树记录了所有样式的规则。</p></li><li><p><strong>渲染树</strong><br> 由 DOM 和 CSSOM 合并而成，每个节点都包含视觉属性。<code>display: none</code> 的节点不会出现在渲染树中，但 <code>visibility: hidden</code> 会占据空间。</p></li><li><p><strong>布局（Layout/Reflow）</strong><br> 从根节点开始，遍历渲染树，计算每个节点在屏幕上的确切坐标和尺寸。<strong>布局是一个递归且可能全局影响的过程</strong>，例如窗口尺寸变化或元素几何属性改变都可能触发全局或局部布局。</p></li><li><p><strong>绘制（Paint）</strong><br> 根据渲染树和布局信息，将元素绘制成像素，填充颜色、边框、阴影等。绘制会生成一些绘制指令。</p></li><li><p><strong>合成（Composite）</strong><br> 现代浏览器会将页面分成多个图层，每个图层独立绘制并上传到 GPU，最终由合成线程合并为一张图显示在屏幕上。<br><strong>重排成本最高，重绘次之，仅合成本最低。</strong></p></li><li><p><strong>常见属性对渲染的影响</strong></p><ul><li><strong>引起重排（导致重新布局）</strong>：<code>width/height</code>、<code>padding</code>、<code>margin</code>、<code>left/top</code>、<code>font-size</code>、<code>display: none</code>、修改 DOM 结构等。</li><li><strong>引起重绘（不重新布局，只重画）</strong>：<code>color</code>、<code>background-color</code>、<code>box-shadow</code> 等外观改变。</li><li><strong>只触发合成（不重排不重绘，性能最优）</strong>：<code>transform</code> 和 <code>opacity</code>（当它们创建了独立合成层时）。</li></ul></li></ul>',3),d=[s];function i(c,l,a,p,g,_){return e(),t("div",null,d)}const h=o(r,[["render",i]]);export{f as __pageData,h as default};
